/* C ref: pline.c vpline() -> vsnprintf.  js/display.js:3124 pline(msg) takes a
 * SINGLE string, so `pline("%s ...", arg)` prints the literal "%s".  This is
 * the minimal C-compatible conversion set actually used by the pline_The call
 * sites in this file; unknown specifiers are left verbatim, which is what a
 * mismatched vsnprintf would do rather than dropping text. */
/* Exported so js/do_wear.js's You()/Your()/yname() share THIS body rather than
 * growing a fourth private formatter — js/potion.js and js/read.js each already
 * carry their own, and js/read.js:2307's `pline("Your " + fmt, ...args)` drops
 * the varargs entirely, printing "%s" to the topline verbatim. */
export function _plineVFmt(fmt, args) {
    let i = 0;
    return String(fmt).replace(/%(?:%|l?[sdcui])/g, (spec) => {
        if (spec === '%%') return '%';
        const a = args[i++];
        if (spec.endsWith('c'))
            return typeof a === 'number' ? String.fromCharCode(a) : String(a);
        if (spec.endsWith('s'))
            return a == null ? '' : String(a);
        /* C's %d/%u are int (wraps at 32 bits, which `| 0` reproduces); %ld/%lu
         * are long and must NOT wrap — `Your("%ld gold pieces...", umoney)`
         * (js/vault.js:91) is the case that would print a negative purse. */
        return spec.length === 3 ? String(Math.trunc(Number(a)) || 0) : String(a | 0);
    });
}

/* C ref: pline.c:417-424 pline_The(line, ...) —
 *   vpline(YouMessage(tmp, "The ", line), the_args)
 * i.e. the formatted message with a literal "The " prefix. */
async function pline_The(fmt, ...args) {
    return pline('The ' + _plineVFmt(fmt, args));
}

/* C ref: pline.c:427-434 You(line, ...) —
 *   vpline(YouMessage(tmp, "You ", line), the_args) — a literal "You " prefix. */
async function _goto_level_You(fmt, ...args) {
    return pline('You ' + _plineVFmt(fmt, args));
}
/* C ref: pline.c:435-452 You_hear — this WAS the tree's only faithful copy of
 * the guard, and it is now the shared body in js/display.js, which is where
 * pline() and the rest of pline.c already live.  Ten other copies disagreed
 * with it; they all forward here now. */
async function _goto_level_You_hear(fmt, ...args) {
    return You_hear(fmt, ...args);
}

/* C ref: you.h:240 #define Role_if(X) (gu.urole.mnum == (X))
 * C ref: you.h:290 #define Race_if(X) (gu.urace.mnum == (X))
 * Race_if was a throw-stub (see its old body, removed below); it sits in the
 * same `||` expression as Role_if at the touchstone check, so binding Role_if
 * alone would only have moved the abort one operand to the right. */
function Role_if(pm) {
    return ((game.urole && game.urole.mnum) | 0) === (pm | 0);
}

/* C ref: mondata.h:135 #define type_is_pname(ptr) (((ptr)->mflags2 & M2_PNAME) != 0L)
 * Mirrors js/mcastu.js:793, which carries the identical body. */
const _M2_PNAME = 0x00080000; /* C ref: monflag.h:141 M2_PNAME 0x00080000L.
                               * Agrees with js/mcastu.js:787, js/makemon.js:153,
                               * js/mhitm.js:258, js/objnam.js:2618,
                               * js/questpgr.js:28 and js/cmd.js:9270. */
function type_is_pname(ptr) {
    return !!ptr && ((ptr.mflags2 | 0) & _M2_PNAME) !== 0;
}

function Shk_Your(obj) {
    let owned = !!obj && (obj.where | 0) === 3;
    if (obj && !owned) {
        for (let o = game.invent; o; o = o.nobj) {
            if (o === obj) { owned = true; break; }
        }
    }
    return (owned ? 'Your' : 'The') + ' ';
}

/* C ref: cfgfiles.c:1856-1864 config_error_add(str, ...) -> vconfig_error_add
 * -> config_erradd(buf): C FORMATS the message and APPENDS it to the pending
 * config-error report, which is emitted later by config_error_done().  It
 * prints nothing at the call site and draws no RNG.
 * The port has no config-file parse path wired to a window, so accumulate on
 * game state and emit nothing — the C-shaped behaviour for everything up to
 * config_error_done(), which the port never reaches. */
function config_error_add(fmt, ...args) {
    const msg = _plineVFmt(fmt, args);
    if (!game._config_errors) game._config_errors = [];
    game._config_errors.push(msg);
}

// Direction deltas: y u k
//                   h . l
//                   b j n
const DIR_DX = { h: -1, l: 1, j: 0, k: 0, y: -1, u: 1, b: -1, n: 1 };
const DIR_DY = { h: 0, l: 0, j: 1, k: -1, y: -1, u: -1, b: 1, n: 1 };
function isMovementKey(ch) {
    return 'hjklyubn'.includes(ch);
}
// builds the mapdump payload, hashes it, and emits both the "mapstate[...
// dump=1]" wrapper and one "md.<line>" event per payload line. That is
// exactly the (build_mapdump + hash + always-dump) sequence emitMapstate()
// already implements in mapstate.js (used by the existing call sites in
// allmain.js/do.js that mirror this C function's callers). No do_hash/
// function always dumps, matching emitMapstate()'s unconditional behavior.
// allmain.js/do.js call sites through this export is a follow-up task.
export function harness_emit_mapstate_dump(phase) {
    emitMapstate(phase);
}
// C ref: cmd.c:2739 move_funcs[] — the uppercase movement keys H/J/K/L/Y/U/B/N
// are bound to do_run_<dir>() (cmd.c:2217), which calls set_move_cmd(dir, 1):
// a shift-run (svc.context.run = 1).  The 8 run keys carry the SAME direction
// deltas as their lowercase walk counterparts:
//   H=DIR_W(h) J=DIR_S(j) K=DIR_N(k) L=DIR_E(l) Y=DIR_NW(y) U=DIR_NE(u)
