        const mon = m_at(x, y);
        if (mon && M_AP_TYPE(mon) === M_AP_FURNITURE
            && mon.mappearance === S_altar)
            res = ((mon.mcorpsenm ?? NON_PM) !== NON_PM) ? (mon.mcorpsenm | 0) : 0;
        else if (IS_ALTAR(_levlAt(x, y).typ))
            res = (_levlAt(x, y).altarmask | 0);
