                const am = ((loc.altarmask ?? loc.flags) | 0) & AM_MASK;
                const atmp = (am === 4) ? 3 : am;
                if (!feat.naltar)
                    feat.msalign = atmp;
                else if (feat.msalign !== atmp)
                    feat.msalign = 0;   /* MSA_NONE */
                bump('naltar');
