    const OBJ_MINVENT_VAL = 4;

    // C: boolean candle = Is_candle(otmp);
    const candle = (otmp.otyp === TALLOW_CANDLE || otmp.otyp === WAX_CANDLE);

    // C: if ((candle || otmp->otyp == CANDELABRUM_OF_INVOCATION) && otmp->lamplit)
