        const findx = Math.min(obj.spestudied | 0, _FTB_MAX_SPELL_STUDY);

        await pline("The%s ink in this spellbook is %s.",
                    _ftb_oc_magic(otyp) ? " magical" : "",
                    fadeness[findx]);
