// C ref: hack.c:1708-1734 notice_mon — accessibility: announce newly spotted monster.
export function notice_mon(mtmp) {
    const g = game;
    const a11y = g.a11y;
    if (a11y && a11y.mon_notices && !a11y.mon_notices_blocked) {
        const mndx = (mtmp.mndx ?? 0) | 0;
        const spot = canspotmon(mtmp)
            && !(_is_hider_mndx(mndx)
                 && (mtmp.mundetected
                     || M_AP_TYPE(mtmp) === M_AP_FURNITURE
                     || M_AP_TYPE(mtmp) === M_AP_OBJECT));

        if (spot && !mtmp.mspotted && !DEADMONSTER(mtmp)) {
            mtmp.mspotted = true;
            set_msg_xy(mtmp.mx, mtmp.my);
            const verb = canseemon(mtmp) ? 'see' : 'notice';
            const monname = x_monnam(mtmp,
                     mtmp.mtame ? ARTICLE_YOUR
                     : (!has_mgivenname(mtmp)
                        && !type_is_pname(mtmp.data)) ? ARTICLE_A
                     : ARTICLE_NONE,
                     (mtmp.mpeaceful && !mtmp.mtame) ? 'peaceful' : 0,
                     has_mgivenname(mtmp) ? SUPPRESS_SADDLE : 0, false);
            /* C ref: pline.c You(line, ...) == vpline(YouMessage("You ", line)).
             * The You imported at the head of this file (js/do_wear.js:2720) is a
             * throw-stub, and pline() takes a single string -- expand both here
             * rather than leave a guaranteed abort on the a11y path. */
            pline('You ' + _plineVFmt('%s %s.', [verb, monname]));
        } else if (!spot) {
            mtmp.mspotted = false;
        }
    }
}

// C ref: hacklib.c:532 visctrl(c) — return string representation of a
// non-printable char. C rotates a static buffer pool so callers can hold
// several results; JS strings are values so we return directly.
export function visctrl(c) {
    let ccc = '';
    if ((c & 0x80) !== 0) {
        ccc += 'M';
        ccc += '-';
    }
    c = c & 0x7f;
    if (c < 0x20) {
        ccc += '^';
        ccc += String.fromCharCode(c | 0x40);
    } else if (c === 0x7f) {
        ccc += '^';
        ccc += String.fromCharCode(c & ~0x40);
    } else {
        ccc += String.fromCharCode(c);
    }
    return ccc;
}

// Stub: do_reqmenu (unported helper for handle_tip TIP_SWIM)
/* C ref: cmd.c:1574-1586 do_reqmenu(void) — the 'm' prefix.
 *     if (iflags.menu_requested) {
 *         Norep("Double %s prefix, canceled.", visctrl(cmd_from_func(do_reqmenu)));
 *         iflags.menu_requested = FALSE;
 *         return ECMD_CANCEL;
 *     }
 *     iflags.menu_requested = TRUE;
 *     return ECMD_OK;
 * Every reader of iflags.menu_requested in this port was already ported (doeat,
 * dodrink, dopickup, doorganize, ...); only the one WRITER was a throwing stub,
 * which is why iactions.c's IA_EAT_OBJ / IA_QUAFF_OBJ / IA_TIP_CONTAINER rows
 * could not queue their m-prefix. */
export async function do_reqmenu() {
    const g = game;
    if (!g.iflags) g.iflags = {};
    if (g.iflags.menu_requested) {
        await _Norep('Double %s prefix, canceled.', _binds_visctrl(cmd_from_func('do_reqmenu')));
        g.iflags.menu_requested = false;
        return STETH_ECMD_CANCEL;
    }
    g.iflags.menu_requested = true;
    return STETH_ECMD_OK;
}

