// ── highc local (same logic as mklev.js highc) ──────────────────────────────
function _highc(c) {
    if (typeof c === 'string') {
        const code = c.charCodeAt(0);
        return ('a'.charCodeAt(0) <= code && code <= 'z'.charCodeAt(0)) ? String.fromCharCode(code & ~0o40) : c;
    }
    return ('a'.charCodeAt(0) <= c && c <= 'z'.charCodeAt(0)) ? (c & ~0o40) : c;
}




const COSTLY_ALTERATION_VERBS = [
    'cancel', 'drain', 'uncharge', 'unbless', 'uncurse', 'disenchant',
    'degrade', 'dilute', 'erase', 'burn', 'neutralize', 'destroy', 'splatter',
    'bite', 'open', 'break the lock on', 'rust', 'rot', 'tarnish', 'crack',
];
export async function costly_alteration(obj, alter_type) {
    const u = game.u || {};

    if (alter_type < 0 || alter_type >= COSTLY_ALTERATION_VERBS.length) {
        /* C: impossible("invalid alteration type (%d)", alter_type); */
        alter_type = 0;
    }

    let ox = 0, oy = 0, objroom = 0;
    if ((obj.where | 0) === 3 /* OBJ_INVENT, carried() */
        || (obj.where | 0) === 0 /* OBJ_FREE */) {
        /* OBJ_FREE catches obj_no_longer_held()'s crysknife -> worm-tooth
           transformation; the item has left inventory but not necessarily
           landed yet, and 'unpaid' survives the move. */
        if (!obj.unpaid)
            return;
    } else {
        const xp = {}, yp = {};
        if (!get_obj_location(obj, xp, yp, 1 /* CONTAINED_TOO */)) {
            xp.value = u.ux | 0;
            yp.value = u.uy | 0;
        }
        ox = xp.value | 0;
        oy = yp.value | 0;
        if (!costly_spot(ox, oy))
            return;
        objroom = in_rooms(ox, oy, SHOPBASE)[0] | 0;
        const shkpBox = { value: null };
        if (!(await shk_billable(shkpBox, obj, objroom, false)))
            return;
    }

    const quan = obj.quan ?? 1;
    const those = quan === 1 ? 'that' : 'those';
    const them = quan === 1 ? 'it' : 'them';

    /* learn_bknown = (alter_type == COST_UNCURS || alter_type == COST_UNBLSS) */
    const learn_bknown = (alter_type === 4 || alter_type === 3);

    switch (obj.where | 0) {
    case 0: /* OBJ_FREE */
    case 3: /* OBJ_INVENT */
        if (learn_bknown)
            set_bknown(obj, 1);
        verbalize(`You ${COSTLY_ALTERATION_VERBS[alter_type]} ${those} `
            + `${_ia_simpleonames(obj)}, you pay for ${them}!`);
        await bill_dummy_object(obj);
        break;
    case 1:
        if (learn_bknown)
            obj.bknown = 1;
        if (costly_spot(u.ux | 0, u.uy | 0)
            && objroom === (u.ushops ? u.ushops.charCodeAt(0) : 0)) {
            verbalize(`You ${COSTLY_ALTERATION_VERBS[alter_type]} ${those}, `
                + `you pay for ${them}!`);
            await bill_dummy_object(obj);
        } else {
            await stolen_value(obj, ox, oy, false, false);
        }
        break;
    }
}

// ── dfeature_at (invent.c) ─────────────────────────────────────────────────
// C ref: invent.c dfeature_at(coordxy x, coordxy y, char *buf)
export function dfeature_at(x, y, buf) {
    const lev = _levlAt(x, y);
    if (!lev) return null;
    const ltyp = lev.typ;
    let dfeature = null;
    const stway = stairway_at(x, y);

    if (IS_DOOR(ltyp)) {
        switch (lev.doormask) {
        case D_NODOOR:
            dfeature = "doorway";
            break;
        case D_ISOPEN:
            dfeature = "open door";
            break;
        case D_BROKEN:
            dfeature = "broken door";
            break;
        default:
            dfeature = "closed door";
            break;
        }
        /* override door description for open drawbridge */
        if (dbridge_is_drawbridge_wall(x, y) >= 0)
            dfeature = "open drawbridge portcullis";
    } else if (IS_FOUNTAIN(ltyp)) {
        dfeature = "fountain";
    } else if (IS_THRONE(ltyp)) {
        dfeature = "opulent throne";
    } else if (is_lava(x, y)) {
        dfeature = "molten lava";
    } else if (is_ice(x, y)) {
        dfeature = ice_descr(x, y);
    } else if (is_pool(x, y)) {
        dfeature = "pool of water";
    } else if (IS_SINK(ltyp)) {
        dfeature = "sink";
    } else if (IS_ALTAR(ltyp)) {
        const high = (lev.altarmask & 0x10) ? "high " : "";
        dfeature = high + "altar to " + a_gname() + " (" + align_str(Amask2align(lev.altarmask & ~AM_SHRINE)) + ")";
    } else if (stway) {
        /* C invent.c:4082 — stairs_description(stway, altbuf, TRUE). */
        dfeature = stairs_description(stway, null, true);
    } else if (ltyp === 34) {  // DRAWBRIDGE_DOWN
        dfeature = "lowered drawbridge";
    } else if (ltyp === 12) {  // DBWALL
        dfeature = "raised drawbridge";
    } else if (IS_GRAVE(ltyp)) {
        dfeature = "grave";
    } else if (ltyp === 13) {  // TREE
        dfeature = "tree";
    } else if (ltyp === 22) {  // IRONBARS
        dfeature = "set of iron bars";
    }

    return dfeature;
}

